function link(page,label){return `<a class="link" href="#${page}">${label}${icon('chevron',13)}</a>`;}
function heading(title,description,primary='Nuevo movimiento',action='create'){return `<div class="page-head"><div><h1>${title}</h1><p class="subtitle">${description}</p></div><div class="head-actions"><button class="btn" data-action="period">${icon(state.page==='dashboard'?'info':'calendar',15)}${state.page==='dashboard'?'Mes actual: septiembre':'Septiembre 2026'}</button><button class="btn primary" data-action="${action}">${icon('plus',15)}<span class="long-label">${primary}</span><span class="short-label" hidden>Nuevo</span></button></div></div>`;}
function navItem(key,label,ico){return `<a class="nav-item ${state.page===key?'active':''}" href="#${key}" title="${label}" ${state.page===key?'aria-current="page"':''}>${icon(ico)}<span class="nav-label">${label}</span>${key==='alerts'?'<span class="count">2</span>':''}</a>`;}
function shell(){
  document.documentElement.dataset.theme=state.theme;
  $('#theme').innerHTML=icon(state.theme==='dark'?'sun':'moon',15);
  $('#theme').setAttribute('aria-label',`Cambiar a modo ${state.theme==='dark'?'claro':'oscuro'}`);
  $('#scenario').value=state.scenario;
  $('#sidebar').innerHTML=`<a href="#dashboard" class="brand" aria-label="FinTrack, inicio">${mark}<span>fintrack</span></a>${navGroups.map(g=>`<div class="eyebrow">${g[0]}</div>${g[1].map(n=>navItem(...n)).join('')}`).join('')}<div class="sidebar-footer">${navItem('alerts','Avisos','bell')}${navItem('admin','Catálogos','grid')}${navItem('settings','Configuración','settings')}<div class="profile"><span class="avatar">AV</span><div class="profile-copy"><strong>Alex Vega</strong><small>Espacio personal</small></div></div></div>`;
  $('#topbar').innerHTML=`<div class="breadcrumb"><button class="icon-btn menu-btn" data-action="menu" aria-label="Abrir navegación">${icon('menu')}</button><span class="space-label">Espacio personal</span><span class="crumb-divider">/</span><strong>${names[state.page]}</strong></div><div class="top-actions"><span class="quiet-status">Registros al 21 de septiembre</span><button class="icon-btn" data-action="privacy" aria-label="Acerca de los datos de muestra">${icon('lock',16)}</button><a class="icon-btn" href="#alerts" aria-label="Avisos, 2 sin leer">${icon('bell',18)}<span class="notification-dot"></span></a><span class="avatar" aria-label="Alex Vega">AV</span></div>`;
  $('#bottom-nav').innerHTML=[['dashboard','Inicio','home'],['transactions','Movimientos','moves'],['create','Registrar','plus'],['portfolio','Cuentas','wallet'],['menu','Más','menu']].map(([id,label,ico])=>['create','menu'].includes(id)?`<button class="bottom-item ${id==='create'?'add':'more'}" data-action="${id}" aria-label="${label}">${icon(ico,20)}${id==='menu'?label:''}</button>`:`<a class="bottom-item ${state.page===id?'active':''}" href="#${id}" ${state.page===id?'aria-current="page"':''}>${icon(ico,19)}${label}</a>`).join('');
}
function empty(module='movimientos'){return `<div class="empty"><div class="empty-icon">${icon(module==='cuentas'?'wallet':'moves',24)}</div><h2>${module==='cuentas'?'Tu primera cuenta, un punto de partida.':'Empieza con lo que ya sabes.'}</h2><p>${module==='cuentas'?'Añade el saldo actual y su fecha. No necesitas cargar todo tu historial.':'Registra una cuenta y después tu primer movimiento. Los resúmenes aparecerán a medida que tengas datos.'}</p><button class="btn primary" data-action="account-create">${icon('plus',16)}Añadir cuenta</button></div>`;}
function chart(){const data=series.slice(-state.period),step=490/data.length,start=48;return `<svg class="chart" viewBox="0 0 560 200" role="img" aria-label="Ingresos y egresos por mes, de abril a septiembre de 2026, en soles. Septiembre está incompleto.">${[0,5000,10000,15000].map(v=>{const y=168-v/15000*140;return `<line class="grid" x1="42" x2="548" y1="${y}" y2="${y}"/><text x="32" y="${y+4}" text-anchor="end">${v===0?'0':v/1000+' mil'}</text>`;}).join('')}${data.map(([m,inc,out],i)=>{let x=start+i*step+step/2;return `<g class="chart-focus" tabindex="0" role="button" aria-label="${m}: ingresos ${money(inc)}, egresos ${money(out)}" data-chart="${m}" data-in="${inc}" data-out="${out}">${m==='Sep'?`<rect class="current-zone" x="${x-step/2+3}" y="14" width="${step-6}" height="157" rx="6"/>`:''}<rect class="income-bar" x="${x-20}" y="${168-inc/15000*140}" width="17" height="${inc/15000*140}" rx="2"/><rect class="expense-bar" x="${x+3}" y="${168-out/15000*140}" width="17" height="${out/15000*140}" rx="2"/><text x="${x}" y="191" text-anchor="middle">${m}${m==='Sep'?'*':''}</text></g>`;}).join('')}</svg>`;}
function dashboard(){return `${heading('Tu dinero, en perspectiva.','Lunes, 21 de septiembre · Una lectura de tus registros.')}<section class="position" aria-label="Posición actual"><div><div class="position-title">Saldos de tus cuentas <button class="icon-btn" style="height:22px;width:24px" data-action="scope" aria-label="Qué incluye el saldo">${icon('info',14)}</button></div><div class="currency-totals"><div class="currency-total"><span class="currency-label">SOLES · PEN</span><strong class="num"><span class="symbol">S/</span>26,840.00</strong></div><div class="currency-total"><span class="currency-label">DÓLARES · USD</span><strong class="num"><span class="symbol">US$</span>3,200.00</strong></div></div><p class="small muted">4 cuentas activas · Cada moneda conserva su valor original.</p></div><div class="position-summary"><div class="fact"><span class="fact-text">${icon('box',14)}Activos registrados</span><strong class="num">${money(38500)}</strong></div><div class="fact"><span class="fact-text">${icon('card',14)}Deuda en tarjeta</span><strong class="num">${money(4800)} <span class="muted small">+ US$ 180.00</span></strong></div><div class="small muted">Son conceptos distintos. No se suman como dinero disponible.</div></div></section><div class="overview-grid"><section class="panel flow-panel"><div class="section-label"><div><h2>El ritmo de tu dinero</h2><p>Ingresos y egresos de tus reportes · PEN</p></div><button class="btn sm" data-action="chart-range">${state.period} meses${icon('chevrondown',12)}</button></div><div class="chart-kpis"><div><p>Ingresos · sep</p><strong class="num positive">${money(12480)}</strong></div><div><p>Egresos · sep</p><strong class="num">${money(7360)}</strong></div><div><p>Resultado · sep</p><strong class="num">${money(5120,'PEN',true)}</strong></div></div>${chart()}<div class="chart-foot"><div class="legend"><span><i class="swatch"></i>Ingresos</span><span><i class="swatch out"></i>Egresos</span></div><span>* Septiembre: del 1 al 21</span></div><div class="tooltip-panel" id="chart-tooltip" role="status"></div><div class="panel-footer"><button class="btn ghost sm" data-action="chart-data">Ver datos del gráfico</button>${link('transactions','Explorar movimientos')}</div></section><section class="panel due-panel"><div class="section-label"><div><h2>En los próximos días</h2><p>Compromisos con fecha registrada</p></div>${icon('calendar',17)}</div>${state.scenario==='error'?`<div class="empty" style="padding:32px 0;margin:0"><div class="empty-icon">${icon('info')}</div><h3>No pudimos cargar los compromisos</h3><p>Los saldos y movimientos siguen disponibles.</p><button class="btn" data-action="retry">Reintentar</button></div>`:`<div class="due-list">${[[23,'Tarjeta Andino','Pago de ciclo · Soles',1200,'Por pagar','credits'],[25,'Estudio Norte','Cobro pendiente',850,'Por cobrar','receivables'],[28,'Préstamo personal','Cuota 08 de 24',680,'Por pagar','credits']].map(([d,n,s,a,t,p])=>`<a class="due-item" href="#${p}"><div class="date-box">SEP<strong>${d}</strong></div><div class="due-body"><div class="due-title">${n}${icon('chevron',12)}</div><p>${s}</p><div class="due-bottom"><strong class="num">${money(a)}</strong><span class="badge ${t==='Por cobrar'?'good':'warn'}">${t}</span></div></div></a>`).join('')}</div><div class="panel-footer"><span class="small muted">Sin pagos automáticos</span>${link('payables','Ver pendientes')}</div>`}</section></div><div class="lower-grid"><section><div class="section-label"><div><h2>Dónde se fue este mes</h2><p>Egresos registrados · 1 al 21 de septiembre · PEN</p></div>${link('transactions','Ver detalle')}</div>${[['Vivienda',2480],['Alimentación',1800],['Compras',1080],['Transporte',860],['Servicios',640],['Otros',500]].map(([n,v])=>`<div class="expense-row"><span>${n}</span><div class="track"><div class="fill" style="width:${v/2480*100}%"></div></div><strong class="num">${money(v)}</strong></div>`).join('')}</section><section><div class="section-label"><div><h2>Tus límites del mes</h2><p>Importes vinculados a presupuestos</p></div>${link('budgets','Ver todos')}</div>${budgets.slice(0,3).map(b=>`<div class="mini-budget ${b.spent>b.limit?'over':''}"><div class="row"><span>${b.name}</span><strong class="num ${b.spent>b.limit?'negative':''}">${(b.spent/b.limit*100).toFixed(1)}%</strong></div><div class="track"><div class="fill" style="width:${Math.min(100,b.spent/b.limit*100)}%"></div></div><small>${money(b.spent)} de ${money(b.limit)}${b.spent>b.limit?` · ${money(b.spent-b.limit)} excedidos`:''}</small></div>`).join('')}</section></div><p class="evidence-note">Los saldos describen hoy; el flujo describe el mes. Una transferencia entre tus cuentas no es un ingreso ni un egreso del reporte.</p>`;}
function filteredTx(){return tx.filter(t=>(state.filter==='all'||t.type===state.filter)&&(state.currency==='all'||t.currency===state.currency)&&`${t.description} ${t.category} ${t.account}`.toLowerCase().includes(state.search.toLowerCase()));}
function txAmount(t){return money(t.type==='expense'?-t.amount:t.amount,t.currency,t.type==='income');}
function txIcon(t){return `<span class="tx-symbol ${t.type==='income'?'in':''}">${icon(t.type==='income'?'down':t.type==='transfer'?'moves':'up',14)}</span>`;}
function transactionRows(){const rows=filteredTx();return `${state.selected.size?`<div class="bulk-bar"><span>${state.selected.size} seleccionados</span><button class="btn sm" data-action="export">Exportar selección</button></div>`:''}<div class="register"><table class="desktop-table"><thead><tr><th class="check-col"><input class="checkbox" type="checkbox" aria-label="Seleccionar movimientos visibles" data-action="select-all" ${rows.length&&rows.every(t=>state.selected.has(t.id))?'checked':''}></th><th>Movimiento</th><th class="col-account">Cuenta</th><th class="col-category">Categoría</th><th>Fecha</th><th class="amount">Importe original</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td class="check-col"><input class="checkbox" type="checkbox" data-select="${t.id}" ${state.selected.has(t.id)?'checked':''} aria-label="Seleccionar ${t.description}"></td><td><div class="tx-cell">${txIcon(t)}<div><button class="row-button" data-detail="${t.id}">${esc(t.description)}</button><small>${t.type==='income'?'Ingreso':t.type==='expense'?'Egreso':'Transferencia interna'}</small></div></div></td><td class="col-account">${t.account}</td><td class="col-category">${t.category}</td><td class="table-date muted">${t.date} 2026</td><td class="amount num ${t.type==='income'?'positive':''}">${txAmount(t)}</td><td><button class="icon-btn" data-detail="${t.id}" aria-label="Abrir ${t.description}">${icon('chevron',14)}</button></td></tr>`).join('')}</tbody></table><div class="mobile-records">${rows.map(t=>`<div class="mobile-record"><div class="mobile-record-head"><div class="tx-cell">${txIcon(t)}<div><button class="row-button" data-detail="${t.id}">${esc(t.description)}</button><small>${t.date} · ${t.category}</small></div></div><strong class="num ${t.type==='income'?'positive':''}">${txAmount(t)}</strong></div><div class="mobile-record-meta"><span>${t.account}</span><button class="icon-btn" data-detail="${t.id}" aria-label="Detalle de ${t.description}">${icon('chevron',14)}</button></div></div>`).join('')}</div>${!rows.length?`<div class="empty"><h2>No hay coincidencias</h2><p>Prueba otra descripción o elimina los filtros.</p><button class="btn" data-action="reset-filters">Limpiar filtros</button></div>`:''}<div class="table-footer"><span>${rows.length} movimientos · Importes originales</span><span>Página 1 de 1</span></div></div>`;}
function transactions(){return `${heading('Movimientos','El registro de lo que entra, sale y se mueve.')}<div class="module-summary"><div><p>Ingresos · PEN</p><strong class="num positive">${money(12480)}</strong></div><div><p>Egresos · PEN</p><strong class="num">${money(7360)}</strong></div><div><p>Resultado del mes · PEN</p><strong class="num">${money(5120,'PEN',true)}</strong><small>Excluye transferencias internas</small></div></div><div class="tabs" aria-label="Tipo de movimiento">${[['all','Todos',12],['income','Ingresos',2],['expense','Egresos',8],['transfer','Transferencias',2]].map(([k,n,c])=>`<button class="tab ${state.filter===k?'active':''}" data-filter="${k}" aria-pressed="${state.filter===k}">${n}<span class="tab-count">${c}</span></button>`).join('')}</div><div class="toolbar"><label class="search">${icon('search',16)}<input id="tx-search" type="search" value="${esc(state.search)}" placeholder="Buscar un movimiento" aria-label="Buscar movimientos"></label><button class="btn" data-action="filters">${icon('filter',15)}Filtros${state.currency!=='all'?' · 1':''}</button><button class="btn saved-view" data-action="saved-view">Vista del mes${icon('chevrondown',12)}</button><div class="toolbar-right"><button class="btn" data-action="export">${icon('download',15)}Exportar</button></div></div><div class="filter-chips"><span class="filter-chip">1–21 sep 2026</span>${state.currency!=='all'?`<button class="filter-chip" data-action="reset-currency">${state.currency}${icon('close',12)}</button>`:''}<span>12 registros de muestra · Sin conexión bancaria</span></div><div id="transaction-rows">${transactionRows()}</div>`;}
function portfolio(){return `${heading('Cuentas','Cada saldo en su moneda. Cada cuenta con su propósito.','Añadir cuenta','account-create')}<div class="module-summary"><div><p>Saldos en soles</p><strong class="num">${money(26840)}</strong><small>3 cuentas activas</small></div><div><p>Saldos en dólares</p><strong class="num">${money(3200,'USD')}</strong><small>1 cuenta activa</small></div><div><p>Registro separado</p><strong style="font-size:16px">Sin consolidar monedas</strong><small>El crédito disponible no es un saldo propio</small></div></div><div class="tabs"><button class="tab active" aria-pressed="true">Activas <span class="tab-count">4</span></button><button class="tab" data-action="inactive-accounts">Inactivas <span class="tab-count">0</span></button><button class="tab" data-action="technical-accounts">Cuentas técnicas</button></div><div class="toolbar"><label class="search">${icon('search',16)}<input id="account-search" type="search" aria-label="Buscar cuentas" placeholder="Buscar por cuenta o entidad"></label><button class="btn" data-action="account-filters">${icon('filter',15)}Moneda y tipo</button><div class="toolbar-right"><span class="small muted">Apertura y posición actual</span></div></div><div class="register" id="account-register">${accountRows(accounts)}</div><p class="evidence-note">La apertura y el saldo actual son dos valores registrados. No representan un historial ni una rentabilidad. Las cuentas técnicas de tarjetas se consultan por separado.</p>`;}
function accountRows(rows){return `<table class="desktop-table"><thead><tr><th>Cuenta</th><th>Tipo</th><th>Moneda</th><th class="amount">Saldo de apertura</th><th class="amount">Saldo actual</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td><div class="account-identity"><span class="bank">${a.code}</span><div><button class="row-button" data-account="${esc(a.name)}">${a.name}</button><small>${a.bank}</small></div></div></td><td>${a.type}</td><td><span class="badge">${a.currency}</span></td><td class="amount"><span class="num muted">${money(a.opening,a.currency)}</span><small>${a.date}</small></td><td class="amount num"><strong>${money(a.balance,a.currency)}</strong></td><td><button class="icon-btn" data-account="${esc(a.name)}" aria-label="Ver ${a.name}">${icon('chevron',14)}</button></td></tr>`).join('')}</tbody></table><div class="mobile-records">${rows.map(a=>`<div class="mobile-record"><div class="mobile-record-head"><div class="account-identity"><span class="bank">${a.code}</span><div><button class="row-button" data-account="${a.name}">${a.name}</button><small>${a.bank} · ${a.currency}</small></div></div><strong class="num">${money(a.balance,a.currency)}</strong></div><div class="mobile-record-meta"><span>Apertura: ${money(a.opening,a.currency)}</span><button class="icon-btn" data-account="${a.name}" aria-label="Ver ${a.name}">${icon('chevron',14)}</button></div></div>`).join('')}</div>${!rows.length?'<div class="empty"><h3>No hay cuentas que coincidan</h3></div>':''}<div class="table-footer"><span>${rows.length} cuentas visibles</span><span>Importes sin conversión</span></div>`;}
function budgetPage(){const rows=state.budget==='over'?budgets.filter(b=>b.spent>b.limit):budgets;return `${heading('Presupuestos','Límites que puedes revisar antes de tu próximo gasto.','Crear presupuesto','budget-create')}<div class="module-summary"><div><p>Asignado · PEN</p><strong class="num">${money(5450)}</strong></div><div><p>Gasto vinculado · PEN</p><strong class="num">${money(4380)}</strong></div><div><p>Disponible · PEN</p><strong class="num">${money(1070)}</strong><small>Un presupuesto excedido por ${money(60)}</small></div></div><div class="tabs"><button class="tab ${state.budget==='all'?'active':''}" data-budget-filter="all">Este mes<span class="tab-count">4</span></button><button class="tab ${state.budget==='over'?'active':''}" data-budget-filter="over">Excedidos<span class="tab-count">1</span></button><button class="tab" data-action="budget-history">Otros períodos</button></div><div class="budget-grid"><div class="register"><table class="desktop-table budget-table"><thead><tr><th>Presupuesto</th><th>Uso del límite</th><th class="amount">Gasto / límite</th><th class="amount">Disponible</th><th></th></tr></thead><tbody>${rows.map((b)=>`<tr class="${b.spent>b.limit?'over':''}"><td><button class="row-button" data-budget="${b.name}">${b.name}</button><small>1–30 sep · Mensual</small></td><td><span class="small num ${b.spent>b.limit?'negative':''}">${(b.spent/b.limit*100).toFixed(1)}%</span><div class="track"><div class="fill" style="width:${Math.min(100,b.spent/b.limit*100)}%"></div></div></td><td class="amount"><strong class="num">${money(b.spent)}</strong><small>de ${money(b.limit)}</small></td><td class="amount num ${b.spent>b.limit?'negative':''}">${money(b.limit-b.spent)}</td><td><button class="icon-btn" data-budget="${b.name}" aria-label="Ver ${b.name}">${icon('chevron',14)}</button></td></tr>`).join('')}</tbody></table><div class="mobile-records">${rows.map(b=>`<div class="budget-mobile-row"><div class="fact"><button class="row-button" data-budget="${b.name}">${b.name}</button><strong class="num ${b.spent>b.limit?'negative':''}">${(b.spent/b.limit*100).toFixed(1)}%</strong></div><div class="track"><div class="fill" style="width:${Math.min(100,b.spent/b.limit*100)}%;background:var(--${b.spent>b.limit?'negative':'accent'})"></div></div><div class="fact"><span>${money(b.spent)} de ${money(b.limit)}</span><span class="${b.spent>b.limit?'negative':'muted'}">${b.spent>b.limit?'Excedido':'Disponible'}</span></div></div>`).join('')}</div><div class="table-footer">Períodos del 1 al 30 de septiembre de 2026</div></div><aside class="note-panel"><span class="badge warn">1 límite superado</span><h2 style="margin-top:14px">Transporte necesita una revisión</h2><p>Registraste ${money(860)} sobre un límite de ${money(800)}. Revisa los movimientos antes de ajustar el presupuesto.</p><button class="btn wide" data-budget="Transporte">Ver movimientos vinculados${icon('chevron',14)}</button><p style="margin-bottom:0;font-size:11px">Editar septiembre solo afecta a este período. Los demás períodos se conservan.</p></aside></div>`;}
function credits(){return `${heading('Créditos','Lo que debes y lo que vence, con cada moneda a la vista.','Añadir crédito','credit-create')}<div class="tabs"><button class="tab active" data-action="credit-all">Tarjetas y préstamos</button><button class="tab" data-action="credit-schedule">Próximos vencimientos</button></div><div class="credit-grid"><section class="credit-row"><div class="section-label"><div><span class="eyebrow">Tarjeta de crédito</span><h2 style="margin-top:6px">Andino Visa</h2></div><span class="badge">Activa</span></div><div class="credit-amounts"><div><small>Deuda en soles</small><strong class="num">${money(4800)}</strong></div><div><small>Deuda en dólares</small><strong class="num">${money(180,'USD')}</strong></div></div><div class="fact"><span>Línea en PEN · Uso equivalente informado</span><strong>35.4%</strong></div><div class="track"><div class="fill" style="width:35.4%"></div></div><p class="small muted">Límite ${money(15500)} · Equivalencia ilustrativa: 1 USD = 3.8000 PEN</p><div class="list-line" style="margin-top:18px"><div><strong>Próximo pago registrado</strong><small>23 sep 2026 · Ciclo de septiembre</small></div><strong class="num">${money(1200)}</strong></div><div class="panel-footer"><button class="btn ghost" data-action="credit-schedule">Ver ciclos y documentos</button><button class="btn" data-action="credit-payment">Registrar pago</button></div></section><section class="credit-row"><div class="section-label"><div><span class="eyebrow">Préstamo bancario</span><h2 style="margin-top:6px">Préstamo personal</h2></div><span class="badge">Activo</span></div><div class="credit-amounts"><div><small>Capital pendiente</small><strong class="num">${money(10800)}</strong></div><div><small>Próxima cuota</small><strong class="num">${money(680)}</strong></div></div><div class="list-line"><span>Fecha de vencimiento</span><strong>28 sep 2026</strong></div><div class="list-line"><span>Cuota registrada</span><strong>08 de 24</strong></div><div class="list-line"><span>Capital / Interés / Seguro / Otros</span><span class="num">500 / 150 / 20 / 10</span></div><div class="panel-footer"><button class="btn ghost" data-action="loan-schedule">Ver cronograma</button><button class="btn" data-action="loan-schedule">Revisar cuota</button></div></section></div><p class="evidence-note">El crédito disponible no se presenta como dinero propio. El cronograma conserva capital, intereses, seguro y otros cargos tal como están registrados.</p>`;}
function obligations(kind){const receivable=kind==='receivables';const noun=receivable?'cobrar':'pagar';return `${heading(`Por ${noun}`,receivable?'Tus pendientes, organizados por persona y moneda.':'Tus compromisos, organizados por persona y moneda.',`Registrar ${receivable?'cobro':'pago'}`,receivable?'collect':'pay')}<div class="module-summary"><div><p>Pendiente documentado · PEN</p><strong class="num">${money(receivable?2850:3100)}</strong></div><div><p>Pendiente documentado · USD</p><strong class="num">${money(receivable?400:250,'USD')}</strong></div><div><p>Con vencimiento próximo</p><strong>1 registro</strong></div></div><div class="warning-banner">${icon('info',17)}<span>Un saldo inicial no tiene moneda identificada. Se conserva por separado y no se suma a los pendientes.</span><button class="btn sm" data-action="unverified">Ver registro</button></div><section class="panel"><div class="section-label"><h2>${receivable?'Personas que te deben':'Personas a las que debes'}</h2><button class="btn sm" data-action="counterparty">${icon('plus',14)}Añadir persona</button></div>${[[receivable?'Estudio Norte':'Servicios Rivera',receivable?850:1100,'PEN','25 sep 2026'],[receivable?'Camila Ruiz':'Martín Rojas',2000,'PEN','Sin fecha'],[receivable?'Taller Horizonte':'Editorial Sur',receivable?400:250,'USD','10 oct 2026']].map(([n,a,c,d])=>`<div class="list-line"><div><button class="row-button" data-obligation="${n}" data-amount="${a}" data-currency="${c}">${n}</button><small>${d} · Pendiente documentado</small></div><div style="text-align:right"><strong class="num">${money(a,c)}</strong><small>Ver cuenta${icon('chevron',12)}</small></div></div>`).join('')}</section>`;}
function assets(){return `${heading('Activos','Valor registrado de tus bienes. Sin rentabilidades supuestas.','Registrar activo','asset-create')}<div class="module-summary"><div><p>Valor registrado · PEN</p><strong class="num">${money(38500)}</strong></div><div><p>Activos registrados</p><strong>2</strong></div><div><p>Valoración</p><strong style="font-size:16px">Declarada por ti</strong><small>No es una cotización de mercado</small></div></div><section class="panel"><div class="section-label"><h2>Registro de activos</h2><span class="badge">Activos</span></div>${[['Vehículo',35000,'Vehículo · 12 ene 2025'],['Equipo de trabajo',3500,'Equipo · 08 mar 2026']].map(([n,a,d])=>`<div class="list-line"><div><button class="row-button" data-asset="${n}">${n}</button><small>${d}</small></div><strong class="num">${money(a)}</strong></div>`).join('')}</section>`;}
function recurring(){return `${heading('Plantillas','Reutiliza un movimiento y revisa los datos antes de registrarlo.','Crear plantilla','template-create')}<div class="warning-banner">${icon('repeat',17)}Las plantillas no registran movimientos ni ejecutan pagos automáticamente.</div><section class="panel"><div class="section-label"><h2>Listas para usar</h2><span class="muted small">2 plantillas</span></div>${[['Alquiler',2480,'Vivienda'],['Internet',120,'Servicios']].map(([n,a,c])=>`<div class="list-line"><div><strong>${n}</strong><small>Egreso · ${c} · Cuenta principal</small></div><div><strong class="num" style="margin-right:18px">${money(a)}</strong><button class="btn sm" data-template="${n}">Usar plantilla${icon('chevron',12)}</button></div></div>`).join('')}</section>`;}
function alerts(){return `${heading('Avisos','Lo que cambió y lo que merece una revisión.','Nuevo aviso','notice-create')}<div class="tabs"><button class="tab active" data-action="unread-notices">Sin leer<span class="tab-count">2</span></button><button class="tab" data-action="read-notices">Leídos</button></div><section class="panel"><div class="list-line"><div><span class="badge warn">Presupuesto</span><h3 style="margin-top:10px">Transporte superó su límite en ${money(60)}</h3><small>El gasto registrado llegó al 107.5% de septiembre.</small><div style="margin-top:14px">${link('budgets','Revisar presupuesto')}</div></div><button class="btn sm" data-action="mark-read">Marcar leído</button></div><div class="list-line"><div><span class="badge blue">Vencimiento</span><h3 style="margin-top:10px">Tu tarjeta vence el 23 de septiembre</h3><small>Hay un pago de ${money(1200)} registrado en el ciclo.</small><div style="margin-top:14px">${link('credits','Ver ciclo')}</div></div><button class="btn sm" data-action="mark-read">Marcar leído</button></div></section><p class="evidence-note">Leer un aviso no paga una deuda ni resuelve el estado financiero que lo originó.</p>`;}
function settings(){return `${heading('Configuración','Preferencias claras, bajo tu control.','Guardar','save-settings')}<div class="settings-layout"><div class="settings-list">${['Perfil','Seguridad','Preferencias','Notificaciones','Datos','Soporte'].map(n=>`<button class="nav-item ${n==='Preferencias'?'active':''}" style="border:0;background:${n==='Preferencias'?'var(--accent-soft)':'transparent'}" data-setting="${n}">${n}</button>`).join('')}</div><section class="panel"><h2>Preferencias</h2><div class="list-line"><div><strong>Apariencia</strong><small>El tema cambia la interfaz, nunca los significados de los colores.</small></div><button class="btn sm" data-action="theme">${state.theme==='light'?'Claro':'Oscuro'}${icon(state.theme==='light'?'sun':'moon',14)}</button></div><div class="list-line"><div><strong>Moneda de presentación</strong><small>Los registros originales siempre mantienen su moneda.</small></div><span class="badge">PEN</span></div><div class="list-line"><div><strong>Privacidad de importes</strong><small>Oculta cifras cuando compartes la pantalla.</small></div><button class="btn sm" data-action="privacy">Ver ejemplo</button></div><p class="evidence-note">Esta preview no guarda preferencias ni accede a tu perfil real.</p></section></div>`;}
function admin(){return `${heading('Catálogos','Los nombres y referencias que organizan tu registro.','Nuevo registro','catalog-create')}<div class="tabs">${['Categorías','Entidades','Monedas','Tipos de activo'].map((n,i)=>`<button class="tab ${i===0?'active':''}" data-catalog="${n}">${n}</button>`).join('')}</div><section class="panel"><h2>Categorías de egresos</h2>${['Vivienda','Alimentación','Transporte','Servicios'].map(n=>`<div class="list-line"><span>${n}</span><span class="badge">Activa</span></div>`).join('')}</section>`;}
function render(){shell();if(state.scenario==='loading'){$('#main').innerHTML='<div role="status" aria-label="Cargando contenido"><div class="skeleton title"></div><div class="skeleton metrics"></div><div class="overview-grid"><div class="skeleton chart-block"></div><div class="skeleton chart-block"></div></div><p class="small muted" style="margin-top:20px">Muestra del estado de carga. Cambia «Estado» para continuar.</p></div>';return;}if(state.scenario==='empty'){$('#main').innerHTML=heading(names[state.page],'Un espacio para construir tu registro financiero.','Añadir cuenta','account-create')+empty('cuentas');return;}const pages={dashboard,transactions,portfolio,budgets:budgetPage,credits,receivables:()=>obligations('receivables'),payables:()=>obligations('payables'),assets,recurring,alerts,settings,admin};$('#main').innerHTML=(state.scenario==='error'?'<div class="warning-banner">'+icon('info',16)+'<span>Una fuente no pudo actualizarse. Conservamos los datos disponibles de esta sesión.</span><button class="btn sm" data-action="retry">Reintentar</button></div>':'')+pages[state.page]();requestAnimationFrame(calibrateChartLabels);}
let lastFocus=null,dirty=false;
function openDialog(title,description,body,footer='',kind='drawer') {lastFocus=document.activeElement;dirty=false;const d=$('#overlay');if(d.open)d.close();d.className=kind;d.innerHTML=`<header class="dialog-header"><div><h2 id="overlay-title">${title}</h2>${description?`<p>${description}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close',20)}</button></header><div class="dialog-body">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}`;d.showModal();}
function closeDialog(){if(dirty){const body=$('.dialog-body',$('#overlay'));if(!$('#discard-note'))body.insertAdjacentHTML('afterbegin','<div class="warning-banner" id="discard-note"><span>Tienes cambios sin guardar.</span><button class="btn sm" data-action="discard">Descartar</button><button class="btn sm" data-action="keep-editing">Seguir editando</button></div>');return;}$('#overlay').close();if(lastFocus?.isConnected)lastFocus.focus();}
function toast(message){clearTimeout(state.toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');state.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function field(label,content,full=false){return `<label class="field ${full?'full':''}"><span>${label}</span>${content}</label>`;}
function form(type='expense',edit=null){state.formType=type;const transfer=type==='transfer',income=['income','receivable_collect','payable_issue'].includes(type);const title=edit?'Editar movimiento':({expense:'Registrar egreso',income:'Registrar ingreso',transfer:'Transferir entre cuentas',asset_purchase:'Comprar un activo',receivable_issue:'Prestar dinero',receivable_collect:'Registrar cobro',payable_issue:'Registrar dinero recibido a devolver',payable_pay:'Registrar pago'}[type]);const amount=edit?.amount||'',description=edit?.description||'',source=edit?.account||'Cuenta principal · PEN';openDialog(title,'Datos de muestra · El registro se simula solo en esta sesión.',`<form id="movement-form"><div class="form-grid">${field('Importe',`<div class="amount-group"><input name="amount" class="amount-input" inputmode="decimal" autocomplete="off" placeholder="0.00" value="${amount}" required aria-label="Importe"><select name="currency" aria-label="Moneda"><option>PEN</option><option>USD</option></select></div><small>Hasta 2 decimales. Ejemplo: 1,250.50</small>`,true)}${field(income?'Cuenta receptora':'Cuenta de origen',`<select name="account"><option>${source}</option><option>Reserva · PEN</option><option>Ahorros en dólares · USD</option><option>Efectivo · PEN</option></select>`,true)}${transfer?field('Cuenta destino','<select name="destination"><option>Reserva · PEN</option><option>Cuenta principal · PEN</option><option>Ahorros en dólares · USD</option></select>',true):field('Categoría','<select name="category"><option>Alimentación</option><option>Vivienda</option><option>Transporte</option><option>Servicios</option><option>Trabajo independiente</option></select>')}${field('Fecha','<input type="date" name="date" value="2026-09-21" required>')}${field('Descripción',`<input name="description" placeholder="¿Qué quieres recordar?" value="${esc(description)}" maxlength="255" required>`,true)}${['receivable_issue','receivable_collect','payable_issue','payable_pay'].includes(type)?field(income?'Persona o cuenta por liquidar':'Persona o cuenta relacionada','<select><option>Estudio Norte · PEN · S/ 850.00</option></select>',true):''}${type==='asset_purchase'?field('Nombre del activo','<input name="asset_name" placeholder="Equipo de trabajo">',true):''}</div><div id="fx-field" hidden class="form-extras">${field('Tipo de cambio USD → PEN','<input name="fx" inputmode="decimal" placeholder="3.8000"><small>Debe ser el tipo de cambio válido del registro, no una tasa inventada.</small>',true)}</div><details class="form-extras"><summary>Más opciones · Notas y presupuesto</summary>${field('Notas <small>Opcional</small>','<textarea name="notes" placeholder="Un detalle adicional"></textarea>')}${field('Presupuesto <small>Opcional</small>','<select name="budget"><option>Sin presupuesto asociado</option><option>Alimentación · Septiembre 2026</option></select>')}</details><div class="effect"><p>Así se registrará</p><div class="fact"><span>${transfer?'Entre tus propias cuentas':income?'Entrada a tu cuenta':'Salida de tu cuenta'}</span><strong id="effect-amount" class="num">${money(Number(amount)||0,'PEN',income)}</strong></div><div class="fact"><span>Efecto en el reporte</span><span>${transfer?'No cuenta como ingreso ni egreso':'Se conserva la regla actual del movimiento'}</span></div></div><div class="inline-error" id="form-error" role="alert"></div></form>`,`<button class="btn" data-action="close">Cancelar</button><button class="btn primary" type="submit" form="movement-form">${edit?'Guardar cambios':'Guardar movimiento'}</button>`,'drawer wide-drawer');}
function create(){const ops=[['expense','Egreso','Un gasto de tu día a día','up'],['income','Ingreso','Dinero que recibiste','down'],['transfer','Transferencia','Entre tus cuentas','moves'],['asset_purchase','Compra de activo','Un bien que conservarás','box'],['receivable_issue','Prestar dinero','Crea un pendiente por cobrar','up'],['receivable_collect','Cobrar','Reduce un pendiente registrado','down'],['payable_issue','Recibir un préstamo','Crea un pendiente por pagar','down'],['payable_pay','Pagar un pendiente','Reduce una obligación registrada','up']];openDialog('¿Qué vas a registrar?','Elige lo que ocurrió. FinTrack mantiene la relación con tus cuentas.',`<div class="operation-grid">${ops.map(([k,n,d,i])=>`<button class="operation" data-operation="${k}">${icon(i,18)}<span><strong>${n}</strong><small>${d}</small></span></button>`).join('')}</div>`,'','drawer');}
function detail(id){const t=tx.find(t=>t.id===id);if(!t)return;openDialog(t.description,'Movimiento registrado · Muestra',`<span class="badge ${t.type==='income'?'good':''}">${t.type==='income'?'Ingreso':t.type==='expense'?'Egreso':'Transferencia'}</span><div class="detail-amount num">${txAmount(t)}</div><p class="small muted">Moneda original: ${t.currency}</p><div class="flow-line"><span>${t.account}</span>${icon(t.type==='income'?'down':'up',14)}<span>${t.category}</span></div><div class="detail-list">${[['Fecha',t.date+' 2026'],['Cuenta',t.account],['Categoría',t.category],['Incluido en reportes',t.type==='transfer'?'No, transferencia interna':'Sí'],['Comprobante','Sin comprobante asociado']].map(([l,v])=>`<div class="fact"><span class="muted">${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="effect"><p>Un registro, sus relaciones</p><span class="small muted">El detalle mantiene juntas la cuenta, la categoría y cualquier vínculo financiero existente.</span></div>`,`<button class="btn danger" data-delete="${id}">Eliminar</button><button class="btn primary" data-edit="${id}">Editar movimiento</button>`);}
function info(title,text){openDialog(title,'Información de la propuesta',`<p style="font-size:13px;line-height:1.8">${text}</p>`,`<button class="btn" data-action="close">Entendido</button>`,'');}
function accountDetail(name){const a=accounts.find(a=>a.name===name);openDialog(a.name,`${a.bank} · ${a.type} · ${a.currency}`,`<p class="small muted">Saldo actual registrado</p><div class="detail-amount num">${money(a.balance,a.currency)}</div><div class="detail-list">${[['Saldo de apertura',money(a.opening,a.currency)],['Fecha de apertura',a.date],['Estado','Activa'],['Moneda',a.currency],['Participación','Cuenta operativa']].map(([l,v])=>`<div class="fact"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="effect">Dos valores registrados. No se deduce una curva histórica ni un rendimiento.</div>`,`<button class="btn" data-action="account-deactivate">Desactivar</button><button class="btn primary" data-action="account-edit">Editar cuenta</button>`);}
function accountForm(){openDialog('Añadir cuenta','Comienza con el saldo que conoces y la fecha a la que corresponde.',`<form id="account-form"><div class="form-grid">${field('Nombre de la cuenta','<input name="name" placeholder="Ej. Mi cuenta de ahorros" required>',true)}${field('Tipo','<select><option>Ahorros</option><option>Corriente</option><option>Efectivo</option><option>Inversión</option></select>')}${field('Moneda','<select><option>PEN</option><option>USD</option><option>EUR</option></select>')}${field('Entidad <small>Opcional</small>','<select><option>Sin entidad</option><option>Banco Andino</option><option>Banco Costa</option></select>',true)}${field('Saldo inicial','<input name="opening" inputmode="decimal" placeholder="0.00" required>')}${field('Fecha del saldo','<input type="date" value="2026-09-21" required>')}</div><div class="effect">La moneda identifica tus registros. Una cuenta con movimientos no se cambia a otra moneda desde este formulario.</div></form>`,`<button class="btn" data-action="close">Cancelar</button><button class="btn primary" form="account-form">Guardar cuenta</button>`);}
function budgetDetail(name){const b=budgets.find(b=>b.name===name);const rows=tx.filter(t=>t.category===name);openDialog(b.name,'Período: 1–30 septiembre 2026 · PEN',`<div class="module-summary"><div><p>Gasto registrado</p><strong class="num">${money(b.spent)}</strong></div><div><p>Límite de septiembre</p><strong class="num">${money(b.limit)}</strong></div></div><span class="badge ${b.spent>b.limit?'bad':'blue'}">${(b.spent/b.limit*100).toFixed(1)}% utilizado</span><h3 style="margin-top:28px">Movimientos vinculados</h3>${rows.map(t=>`<div class="list-line"><div><button class="row-button" data-detail="${t.id}">${t.description}</button><small>${t.date}</small></div><strong class="num">${money(t.amount)}</strong></div>`).join('')}<p class="evidence-note">La edición se aplica al período seleccionado, no a toda la serie.</p>`,`<button class="btn" data-action="close">Cerrar</button><button class="btn primary" data-action="budget-edit">Editar este período</button>`);}
function schedule(loan=false){openDialog(loan?'Cronograma del préstamo':'Ciclo de tarjeta',loan?'Cuotas registradas · Desglose conservado':'Ciclo de septiembre · Importe registrado',loan?`<div class="detail-amount num">${money(680)}</div><p class="small muted">Cuota 08 de 24 · Vence el 28 sep 2026</p><div class="detail-list">${[['Capital',500],['Intereses',150],['Seguro',20],['Otros',10]].map(([n,v])=>`<div class="fact"><span>${n}</span><strong class="num">${money(v)}</strong></div>`).join('')}</div><p class="evidence-note">Si falta un componente del cronograma, se mostrará como no verificable. Nunca se reparte un total mediante una fórmula nueva.</p>`:`<div class="detail-amount num">${money(1200)}</div><p class="small muted">Pago registrado · Vencimiento 23 sep 2026 · PEN</p><div class="detail-list"><div class="fact"><span>Estado de lectura</span><strong>Registrado</strong></div><div class="fact"><span>Moneda</span><strong>PEN</strong></div><div class="fact"><span>Documento asociado</span><strong>Sin documento</strong></div></div><p class="evidence-note">No es un pago mínimo calculado por FinTrack. Solo se presenta el importe almacenado en el ciclo.</p>`,`<button class="btn" data-action="close">Cerrar</button><button class="btn primary" data-action="credit-payment">Registrar pago</button>`);}
function download(){const rows=state.selected.size?tx.filter(t=>state.selected.has(t.id)):filteredTx();const csv='Fecha,Descripción,Tipo,Moneda,Importe\n'+rows.map(t=>[t.date+' 2026',t.description,t.type,t.currency,t.amount].map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='fintrack-v3-synthetic.csv';a.click();URL.revokeObjectURL(url);toast('Archivo de muestra exportado. Solo contiene datos ficticios.');}
function action(a){switch(a){
  case 'create':create();break;case 'close':closeDialog();break;case 'discard':dirty=false;closeDialog();break;case 'keep-editing':$('#discard-note')?.remove();break;
  case 'theme':state.theme=state.theme==='light'?'dark':'light';render();break;
  case 'retry':state.scenario='ready';render();toast('Fuente recuperada en la simulación.');break;
  case 'scope':info('Qué incluye esta posición','Saldos de cuentas activas, separados por moneda y sin cuentas técnicas de tarjeta. Incluye cuentas de ahorro, efectivo e inversión si están registradas. No significa que todo sea retirable hoy. Activos, cobros pendientes y crédito disponible se muestran por separado.');break;
  case 'privacy':info('Un espacio de revisión seguro','Todos los nombres, importes y entidades de esta preview son ficticios. No existe conexión con Supabase. Las interacciones simulan el diseño; las cifras de los resúmenes permanecen fijas para poder comparar las pantallas.');break;
  case 'period':info('Alcance del período','Los movimientos y el gasto por categoría corresponden a septiembre de 2026. Los saldos son actuales y no cambian al elegir un mes. Esta propuesta no ofrece un filtro global que los servicios actuales no puedan cumplir. La selección de meses históricos se habilitará solo en secciones cuyo contrato ya admita fechas.');break;
  case 'chart-range':state.period=state.period===6?3:6;render();break;
  case 'chart-data':openDialog('Datos del gráfico','PEN · Septiembre incluye solo el 1 al 21',`<table><thead><tr><th>Mes</th><th class="amount">Ingresos</th><th class="amount">Egresos</th></tr></thead><tbody>${series.slice(-state.period).map(([m,i,e])=>`<tr><td>${m} 2026</td><td class="amount num">${money(i)}</td><td class="amount num">${money(e)}</td></tr>`).join('')}</tbody></table>`,`<button class="btn" data-action="close">Cerrar</button>`);break;
  case 'filters':openDialog('Filtrar movimientos','Se aplican al registro, no a los saldos actuales.',`<form id="filter-form"><div class="form-grid">${field('Moneda',`<select name="currency"><option value="all">Todas las monedas</option><option ${state.currency==='PEN'?'selected':''}>PEN</option><option ${state.currency==='USD'?'selected':''}>USD</option></select>`,true)}${field('Tipo',`<select name="type">${[['all','Todos'],['income','Ingresos'],['expense','Egresos'],['transfer','Transferencias']].map(([v,n])=>`<option value="${v}" ${state.filter===v?'selected':''}>${n}</option>`).join('')}</select>`,true)}</div><p class="evidence-note">La muestra de movimientos contiene PEN. USD permite revisar el estado sin resultados.</p></form>`,`<button class="btn" data-action="reset-filters">Restablecer</button><button class="btn primary" form="filter-form">Aplicar filtros</button>`);break;
  case 'reset-filters':state.filter='all';state.currency='all';state.search='';state.selected.clear();dirty=false;if($('#overlay').open)closeDialog();render();break;
  case 'reset-currency':state.currency='all';render();break;
  case 'saved-view':openDialog('Vistas del registro','El corte se conserva mientras revisas esta preview.',`<button class="operation" data-view="all" style="width:100%">${icon('calendar')}<span><strong>Vista del mes</strong><small>Todos los movimientos de septiembre</small></span></button><button class="operation" data-view="expense" style="width:100%;margin-top:10px">${icon('up')}<span><strong>Solo egresos</strong><small>El mismo período, sin ingresos ni transferencias</small></span></button>`,'','');break;
  case 'export':download();break;case 'select-all':{const rows=filteredTx();const clear=rows.every(t=>state.selected.has(t.id));rows.forEach(t=>clear?state.selected.delete(t.id):state.selected.add(t.id));$('#transaction-rows').innerHTML=transactionRows();break;}
  case 'account-create':accountForm();break;
  case 'account-edit':info('Edición de cuenta','La presentación cambia; la identidad financiera se conserva. Nombre, notas y apariencia siguen editables. Moneda y el cambio entre cuenta operativa y tarjeta mantienen las restricciones actuales.');break;
  case 'account-deactivate':openDialog('Desactivar esta cuenta','La cuenta dejaría de aparecer entre las activas.',`<p class="small muted">En la app real se comprueban las relaciones antes de permitir esta acción. Esta preview solo simula la confirmación.</p>`,`<button class="btn" data-action="close">Cancelar</button><button class="btn danger" data-action="simulate">Simular desactivación</button>`,'');break;
  case 'inactive-accounts':info('No hay cuentas inactivas','El filtro mostrará las cuentas desactivadas con su acción de reactivación. En este conjunto de muestra todas las cuentas están activas.');break;
  case 'technical-accounts':info('Cuentas técnicas','Una tarjeta puede tener una cuenta técnica asociada. Se mantiene separada de tus saldos propios; su deuda, límite y disponibilidad se consultan en Créditos.');break;
  case 'account-filters':openDialog('Filtrar cuentas','Solo cambia las filas visibles.',`<form id="account-filter-form">${field('Moneda','<select name="currency"><option value="all">Todas</option><option>PEN</option><option>USD</option></select>')}</form>`,`<button class="btn" data-action="close">Cancelar</button><button class="btn primary" form="account-filter-form">Aplicar</button>`,'');break;
  case 'budget-create':case 'budget-edit':openDialog(a==='budget-create'?'Crear presupuesto':'Editar septiembre','La acción afecta exclusivamente a este registro o período.',`<form id="demo-form"><div class="form-grid">${field('Nombre','<input placeholder="Ej. Alimentación" required>',true)}${field('Límite en PEN','<input inputmode="decimal" placeholder="0.00" required>')}${field('Período','<select><option>Septiembre 2026</option></select>')}</div><div class="effect">No se modificarán otros períodos de la serie.</div></form>`,`<button class="btn" data-action="close">Cancelar</button><button class="btn primary" form="demo-form">Guardar período</button>`);break;
  case 'budget-history':info('Períodos de presupuesto','Se podrá seleccionar un período existente con sus fechas completas. La muestra está fijada en septiembre de 2026; no fabrica valores para meses sin registros.');break;
  case 'credit-schedule':schedule();break;case 'loan-schedule':schedule(true);break;case 'credit-all':break;
  case 'credit-create':openDialog('Añadir crédito','Cada producto tiene datos y reglas propios.',`<div class="operation-grid"><button class="operation" data-action="credit-card-form">${icon('card')}<span><strong>Tarjeta de crédito</strong><small>Línea, deuda PEN y deuda USD</small></span></button><button class="operation" data-action="loan-form">${icon('file')}<span><strong>Préstamo bancario</strong><small>Desembolso y cronograma</small></span></button></div>`);break;
  case 'credit-card-form':info('Formulario de tarjeta','Entidad emisora, nombre, línea de crédito y moneda, saldo inicial PEN y USD, cierre y pago. El documento maestro fija el orden, validaciones y estados de este formulario. La muestra interactiva completa es el formulario de movimiento.');break;
  case 'loan-form':schedule(true);break;
  case 'credit-payment':form('expense',{amount:1200,description:'Pago de tarjeta Andino',account:'Cuenta principal · PEN'});break;
  case 'collect':form('receivable_collect');break;case 'pay':form('payable_pay');break;
  case 'unverified':info('Saldo inicial sin moneda','Se conserva el valor histórico 500.00, pero no se le asigna PEN ni USD. No se incorpora a ningún total. Una migración futura requerirá identificar la moneda con evidencia y aprobación independiente.');break;
  case 'counterparty':openDialog('Añadir persona','El contacto y las obligaciones son registros distintos.',`<form id="demo-form"><div class="form-grid">${field('Nombre','<input required placeholder="Persona o empresa">',true)}${field('Notas <small>Opcional</small>','<textarea></textarea>',true)}</div></form>`,`<button class="btn" data-action="close">Cancelar</button><button class="btn primary" form="demo-form">Guardar</button>`);break;
  case 'asset-create':form('asset_purchase');break;case 'template-create':form('expense');break;
  case 'notice-create':openDialog('Crear aviso manual','Un aviso informativo no ejecuta reglas ni pagos.',`<form id="demo-form">${field('Nombre','<input required placeholder="Revisar presupuesto">',true)}<div style="margin-top:16px">${field('Detalle','<textarea required></textarea>',true)}</div></form>`,`<button class="btn" data-action="close">Cancelar</button><button class="btn primary" form="demo-form">Guardar aviso</button>`);break;
  case 'mark-read':toast('Aviso leído en la simulación. La obligación conserva su estado.');break;case 'read-notices':info('Avisos leídos','Esta bandeja indica qué avisos ya revisaste. «Leído» nunca se presenta como «Pagado» o «Resuelto».');break;case 'unread-notices':render();break;
  case 'save-settings':toast('Preferencias de muestra. No se guarda información real.');break;
  case 'catalog-create':info('Nuevo registro del catálogo','La implementación conservará los formularios y restricciones por catálogo, incluidos los registros de sistema. El plan define su composición visual.');break;
  case 'simulate':dirty=false;closeDialog();toast('Acción simulada. No se modificaron registros.');break;
  case 'menu':openDialog('Tu espacio','Todos los módulos, con el mismo orden.',`${navGroups.map(g=>`<p class="eyebrow" style="margin:18px 12px 8px">${g[0]}</p>${g[1].map(n=>navItem(...n)).join('')}`).join('')}${navItem('alerts','Avisos','bell')}${navItem('admin','Catálogos','grid')}${navItem('settings','Configuración','settings')}`);break;
}}
document.addEventListener('click',e=>{
  const target=e.target.closest('button,a,[data-chart]');if(!target)return;
  if(target.dataset.action){action(target.dataset.action);return;}
  if(target.dataset.operation)form(target.dataset.operation);
  if(target.dataset.detail)detail(Number(target.dataset.detail));
  if(target.dataset.edit){const record=tx.find(t=>t.id===Number(target.dataset.edit));form(record.type,record);}
  if(target.dataset.delete){const t=tx.find(t=>t.id===Number(target.dataset.delete));openDialog('Eliminar movimiento','Revisa el registro antes de continuar.',`<div class="effect" style="margin:0"><p>${t.description}</p><strong class="num">${txAmount(t)}</strong><p class="muted small" style="margin-top:10px">${t.date} 2026 · ${t.account}</p></div><p class="evidence-note">La app real validará vínculos y efectos sobre saldos. La preview no elimina datos.</p>`,`<button class="btn" data-action="close">Conservar</button><button class="btn danger" data-action="simulate">Simular eliminación</button>`,'');}
  if(target.dataset.filter){state.filter=target.dataset.filter;state.selected.clear();render();}
  if(target.dataset.view){state.filter=target.dataset.view;dirty=false;closeDialog();render();}
  if(target.dataset.account)accountDetail(target.dataset.account);
  if(target.dataset.budgetFilter){state.budget=target.dataset.budgetFilter;render();}
  if(target.dataset.budget)budgetDetail(target.dataset.budget);
  if(target.dataset.chart){const t=$('#chart-tooltip');t.classList.add('open');t.textContent=`${target.dataset.chart} 2026 · Ingresos ${money(+target.dataset.in)} · Egresos ${money(+target.dataset.out)} · Resultado ${money(+target.dataset.in-target.dataset.out,'PEN',true)}`;}
  if(target.dataset.obligation){const n=target.dataset.obligation;openDialog(n,'Cuenta documentada · Moneda original',`<span class="badge warn">Pendiente</span><div class="detail-amount num">${money(+target.dataset.amount,target.dataset.currency)}</div><div class="detail-list"><div class="fact"><span>Saldo inicial no verificado</span><strong>Se conserva por separado</strong></div><div class="fact"><span>Estado</span><strong>Pendiente</strong></div></div>`,`<button class="btn" data-action="close">Cerrar</button><button class="btn primary" data-action="${state.page==='receivables'?'collect':'pay'}">Registrar ${state.page==='receivables'?'cobro':'pago'}</button>`);}
  if(target.dataset.asset)info(target.dataset.asset,'Valor de compra, valor actual registrado, tipo de activo, fecha de compra, estado y movimiento de origen quedan reunidos en este detalle. Los adjuntos no soportados mantienen su advertencia y las referencias históricas se conservan.');
  if(target.dataset.template)form('expense',{amount:target.dataset.template==='Alquiler'?2480:120,description:target.dataset.template,account:'Cuenta principal · PEN'});
  if(target.dataset.setting)info(target.dataset.setting,'La propuesta conserva esta sección y sus acciones actuales. La sección Preferencias muestra el tratamiento visual. El documento maestro especifica el contenido y las pruebas para Perfil, Seguridad, Notificaciones, Datos y Soporte.');
  if(target.dataset.catalog)info(target.dataset.catalog,'Registros editables en tabla con búsqueda, estado y menú de acciones. Los registros de sistema mantienen restricciones explícitas. No se elimina ni fusiona ningún catálogo de datos.');
});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-chart]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();}});
document.addEventListener('input',e=>{
  if(e.target.id==='tx-search'){state.search=e.target.value;$('#transaction-rows').innerHTML=transactionRows();}
  if(e.target.id==='account-search')$('#account-register').innerHTML=accountRows(accounts.filter(a=>`${a.name} ${a.bank}`.toLowerCase().includes(e.target.value.toLowerCase())));
  if(e.target.closest('#movement-form,#account-form,#demo-form'))dirty=true;
  if(e.target.name==='amount'&&$('#effect-amount')){$('#effect-amount').textContent=money(Number(e.target.value.replace(/,/g,''))||0,$('[name="currency"]',$('#movement-form')).value);}
});
document.addEventListener('change',e=>{
  if(e.target.dataset.select){const id=+e.target.dataset.select;state.selected.has(id)?state.selected.delete(id):state.selected.add(id);$('#transaction-rows').innerHTML=transactionRows();}
  if(e.target.name==='currency'&&e.target.closest('#movement-form')){$('#fx-field').hidden=e.target.value!=='USD';$('[name="fx"]').required=e.target.value==='USD';dirty=true;}
});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;
  if(f.id==='filter-form'){const data=new FormData(f);state.currency=data.get('currency');state.filter=data.get('type');dirty=false;closeDialog();render();return;}
  if(f.id==='account-filter-form'){const c=new FormData(f).get('currency');dirty=false;closeDialog();$('#account-register').innerHTML=accountRows(accounts.filter(a=>c==='all'||a.currency===c));return;}
  if(f.id==='movement-form'){const data=new FormData(f);const amount=String(data.get('amount')).replace(/,/g,'');const valid=/^\d+(\.\d{1,2})?$/.test(amount)&&Number(amount)>0&&Number(amount)<=100000000;if(!valid){$('#form-error').textContent='Introduce un importe mayor que cero y de hasta 2 decimales.';$('[name="amount"]').focus();return;}if(data.get('currency')==='USD'&&!(Number(data.get('fx'))>0)){$('#form-error').textContent='Introduce un tipo de cambio válido mayor que cero.';return;}dirty=false;closeDialog();toast('Movimiento simulado. Los importes de revisión permanecen fijos.');return;}
  if(['account-form','demo-form'].includes(f.id)){dirty=false;closeDialog();toast('Registro simulado. No se enviaron datos ni cambiaron los resúmenes.');}
});
$('#overlay').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('#theme').addEventListener('click',()=>action('theme'));
$('#scenario').addEventListener('change',e=>{state.scenario=e.target.value;render();});
window.addEventListener('hashchange',()=>{if(!names[location.hash.slice(1)])return;dirty=false;if($('#overlay').open)$('#overlay').close();state.page=location.hash.slice(1);state.selected.clear();state.scenario='ready';render();window.scrollTo(0,0);});
render();
